-- Original AI-assisted development content around TOEIC-style workplace topics, not official TOEIC material.
-- 30 topics with one 20-sense lesson each. Every sense has two contexts, one definition-match exercise
-- (wrong choices are other definitions from the same lesson) and two typing-cloze exercises.
-- Levels are an editorial grouping, not verified CEFR or frequency data.
-- Apply once in a transaction after seed.sql; conflicts abort instead of overwriting data.
create temporary table toeic_topic_batch (
  id text primary key, level text not null, title text not null, lesson_title text not null,
  position integer not null
) on commit drop;

create temporary table toeic_sense_batch (
  topic_id text not null references toeic_topic_batch (id), word text not null, part text not null,
  definition text not null, gloss text not null, collocations text[] not null,
  context1 text not null, context2 text not null, distractor1 text not null, distractor2 text not null,
  primary key (topic_id, word)
) on commit drop;

