do $$ begin
  if (select count(*) from toeic_topic_batch) <> 30
    or (select count(*) from toeic_sense_batch) <> 600
    or exists (select 1 from toeic_sense_batch group by topic_id having count(*) <> 20)
    or (select count(distinct lower(word)) from toeic_sense_batch) <> 600
    or exists (select 1 from toeic_sense_batch
      where regexp_count(context1, '\m' || word || '\M', 1, 'i') <> 1
        or regexp_count(context2, '\m' || word || '\M', 1, 'i') <> 1
        or context1 = context2
        or distractor1 in (word, distractor2) or distractor2 = word)
    or exists (select 1 from toeic_sense_batch s
      where not exists (select 1 from toeic_sense_batch d where d.topic_id = s.topic_id and d.word = s.distractor1)
        or not exists (select 1 from toeic_sense_batch d where d.topic_id = s.topic_id and d.word = s.distractor2))
  then raise exception 'TOEIC topic batch validation failed'; end if;
  if exists (select 1 from public.vocabulary_senses v join toeic_sense_batch s on lower(v.headword) = lower(s.word))
  then raise exception 'TOEIC topic batch repeats a headword already in the catalog'; end if;
end $$;

insert into public.curriculum_topics (id, course_id, level_id, title, position)
select id, 'workplace-english', level, title, position from toeic_topic_batch;

insert into public.curriculum_lessons (id, topic_id, title, position)
select id || '-core', id, lesson_title, 0 from toeic_topic_batch;

insert into public.vocabulary_senses
  (id, lesson_id, headword, part_of_speech, definition, vi_gloss, collocations, version)
select topic_id || '-' || word, topic_id || '-core', word, part, definition, gloss, collocations, 1
from toeic_sense_batch;

insert into public.vocabulary_contexts (sense_id, id, example)
select topic_id || '-' || word, 'situation-one', context1 from toeic_sense_batch
union all
select topic_id || '-' || word, 'situation-two', context2 from toeic_sense_batch;

insert into public.exercises (id, sense_id, context_id, kind, prompt, explanation, version, payload)
select s.topic_id || '-' || s.word || '-meaning', s.topic_id || '-' || s.word, 'situation-one',
  'definition-match'::public.exercise_kind,
  '“' || s.context1 || '” What does “' || s.word || '” mean here?',
  '“' || s.word || '” means ' || s.definition || '.', 1,
  jsonb_build_object(
    'choices', jsonb_build_array(
      jsonb_build_object('id', s.word, 'text', upper(left(s.definition, 1)) || substr(s.definition, 2)),
      jsonb_build_object('id', d1.word, 'text', upper(left(d1.definition, 1)) || substr(d1.definition, 2)),
      jsonb_build_object('id', d2.word, 'text', upper(left(d2.definition, 1)) || substr(d2.definition, 2))),
    'correctChoiceId', s.word)
from toeic_sense_batch s
join toeic_sense_batch d1 on d1.topic_id = s.topic_id and d1.word = s.distractor1
join toeic_sense_batch d2 on d2.topic_id = s.topic_id and d2.word = s.distractor2
union all
select topic_id || '-' || word || '-one', topic_id || '-' || word, 'situation-one',
  'typing-cloze'::public.exercise_kind, regexp_replace(context1, '\m' || word || '\M', '___', 'i'),
  '“' || word || '” means ' || definition || '.', 1, jsonb_build_object('acceptedAnswers', jsonb_build_array(word))
from toeic_sense_batch
union all
select topic_id || '-' || word || '-two', topic_id || '-' || word, 'situation-two',
  'typing-cloze'::public.exercise_kind, regexp_replace(context2, '\m' || word || '\M', '___', 'i'),
  '“' || word || '” means ' || definition || '.', 1, jsonb_build_object('acceptedAnswers', jsonb_build_array(word))
from toeic_sense_batch;

do $$ begin
  if (select count(*) from public.curriculum_lessons where id like 'toeic-%-core') <> 30
    or (select count(*) from public.vocabulary_senses where lesson_id like 'toeic-%-core') <> 600
    or (select count(*) from public.exercises e join public.vocabulary_senses s on s.id = e.sense_id
        where s.lesson_id like 'toeic-%-core') <> 1800
    or exists (select 1 from public.exercises e join public.vocabulary_senses s on s.id = e.sense_id
        where s.lesson_id like 'toeic-%-core' and e.kind = 'typing-cloze' and position('___' in e.prompt) = 0)
  then raise exception 'TOEIC topic batch import check failed'; end if;
end $$;
